style:
/* 灰阶 —— 左栏信息、右栏履历带节点导轨 */

.tw-huijie.layout-sidebar.resume-paper {
  padding-top: 15mm;
}

.tw-huijie.layout-sidebar.resume-paper .paper-header {
  margin: 0 0 6.5mm;
  padding: 0 0 4mm;
  background: none;
  border-bottom: 0.25mm solid #e2e5e7;
  color: #242a2d;
  align-items: center;
  gap: 7mm;
}

.tw-huijie.layout-sidebar.resume-paper .paper-photo {
  order: -1;
  width: 25mm;
  height: 25mm;
  border: none;
  border-radius: 50%;
  box-shadow: none;
  object-fit: cover;
}

.tw-huijie.layout-sidebar.resume-paper .paper-photo--monogram {
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #f1f3f4;
  color: #6f7a80;
  font-size: calc(var(--paper-base-size) * 1.9);
  font-weight: 700;
}

.tw-huijie.layout-sidebar.resume-paper .paper-name {
  color: #1f2427;
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 2.1);
  letter-spacing: 0.06em;
}

.tw-huijie.layout-sidebar.resume-paper .paper-identity {
  padding: 0;
  border: none;
  color: #7b858a;
  font-size: calc(var(--paper-base-size) * 0.84);
}

.tw-huijie.layout-sidebar.resume-paper .paper-role {
  margin-top: 1.4mm;
  color: #4a5357;
  font-size: calc(var(--paper-base-size) * 0.9);
  font-weight: 400;
}

.tw-huijie.layout-sidebar.resume-paper .paper-contacts {
  margin-top: 2.6mm;
  color: #3f484c;
  font-size: calc(var(--paper-base-size) * 0.85);
  gap: 1.2mm 6mm;
}

.tw-huijie.layout-sidebar.resume-paper .paper-contact__label {
  color: #889399;
}

.tw-huijie.layout-sidebar.resume-paper .sidebar-layout {
  grid-template-columns: 50mm minmax(0, 1fr);
  column-gap: 10mm;
}

.tw-huijie.layout-sidebar.resume-paper .sidebar-aside {
  grid-column: 1;
  padding: 0 8mm 0 0;
  background: none;
  border-top: none;
  border-right: 0.25mm solid #e2e5e7;
}

.tw-huijie.layout-sidebar.resume-paper .sidebar-main {
  grid-column: 2;
}

.tw-huijie.layout-sidebar.resume-paper .sidebar-aside .paper-section__title {
  display: block;
  margin-bottom: 2.4mm;
  padding: 0 0 1mm;
  border: none;
  border-bottom: 0.22mm solid #e2e5e7;
  color: #262b2e;
  font-size: calc(var(--paper-base-size) * 0.95);
  letter-spacing: 0.1em;
}

.tw-huijie.layout-sidebar.resume-paper .sidebar-aside .paper-section__icon {
  display: none;
}

.tw-huijie.layout-sidebar.resume-paper .sidebar-main .paper-section {
  position: relative;
  padding-left: 5.4mm;
  border-left: 0.25mm solid #c9d0d4;
}

.tw-huijie.layout-sidebar.resume-paper .sidebar-main .paper-section__title {
  position: relative;
  display: block;
  margin-bottom: 2.8mm;
  padding-bottom: 1.2mm;
  border: none;
  border-bottom: 0.22mm solid #e2e5e7;
  color: #1f2427;
  font-size: calc(var(--paper-base-size) * 1.06);
  letter-spacing: 0.08em;
}

.tw-huijie.layout-sidebar.resume-paper .sidebar-main .paper-section__title::before {
  content: "";
  position: absolute;
  top: 0.5mm;
  left: -6.6mm;
  width: 2.4mm;
  height: 2.4mm;
  border-radius: 50%;
  background: #fff;
  border: 0.3mm solid #33393d;
  print-color-adjust: exact;
}

.tw-huijie.layout-sidebar.resume-paper .sidebar-main .paper-section__icon {
  display: none;
}

.tw-huijie.layout-sidebar.resume-paper .paper-section__body {
  color: #33393d;
}

.tw-huijie.layout-sidebar.resume-paper .paper-item-title {
  color: #1f2427;
  font-size: calc(var(--paper-base-size) * 1.02);
}

.tw-huijie.layout-sidebar.resume-paper .paper-item-period {
  color: #7b858a;
  font-size: calc(var(--paper-base-size) * 0.86);
}

.tw-huijie.layout-sidebar.resume-paper .paper-item-sub {
  color: #465055;
}

.tw-huijie.layout-sidebar.resume-paper .paper-rich ul,
.tw-huijie.layout-sidebar.resume-paper .paper-rich ol {
  padding-left: 1.1em;
}

.tw-huijie.layout-sidebar.resume-paper .paper-rich li::marker {
  color: #9aa3a8;
}

.tw-huijie.layout-sidebar.resume-paper .sidebar-aside .paper-skills {
  grid-template-columns: minmax(0, 1fr);
  gap: 1.6mm;
}

.tw-huijie.layout-sidebar.resume-paper .sidebar-aside .paper-skill {
  padding-bottom: 0.8mm;
  border-bottom: 0.2mm solid #eceff0;
}

.tw-huijie.layout-sidebar.resume-paper .sidebar-aside .paper-skill__name {
  display: flex;
  flex: 1;
  align-items: baseline;
  gap: 2mm;
  font-size: calc(var(--paper-base-size) * 0.88);
  font-weight: 400;
}

.tw-huijie.layout-sidebar.resume-paper .sidebar-aside .paper-skill__name::after {
  content: "";
  flex: 1;
  border-bottom: 0.2mm dotted #ccd2d6;
}

.tw-huijie.layout-sidebar.resume-paper .sidebar-aside .paper-skill__dots {
  display: none;
}

.tw-huijie.layout-sidebar.resume-paper .sidebar-aside .paper-skill__level {
  display: inline;
  color: #758087;
  font-size: calc(var(--paper-base-size) * 0.8);
}

.tw-huijie.layout-sidebar.resume-paper .paper-note__tag {
  color: #1f2427;
  font-weight: 600;
}

.tw-huijie.layout-sidebar.resume-paper .paper-footer {
  border-top: 0.2mm solid #e4e7e9;
  color: #9aa3a8;
}
